import { mkdir, writeFile, rename } from 'node:fs/promises';
import { resolve } from 'node:path';
const UA='maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const API='https://tnmaccess.nationalmap.gov/api/v1/products';
const dir=resolve('.cache/usgs/products');
await mkdir(dir,{recursive:true});
const offsets=[];for(let o=0;o<24000;o+=1000)offsets.push(o);
let next=0,done=0,fail=[];
async function worker(){
  while(true){const i=next++;if(i>=offsets.length)return;const offset=offsets[i];
    const url=new URL(API);for(const [k,v] of Object.entries({datasets:'Historical Topographic Maps',max:'1000',offset:String(offset),outputFormat:'JSON'}))url.searchParams.set(k,v);
    let ok=false;
    for(let a=1;a<=4&&!ok;a++){
      try{const r=await fetch(url.href,{headers:{accept:'application/json','user-agent':UA},signal:AbortSignal.timeout(120000)});
        if(!r.ok)throw new Error('HTTP '+r.status);
        const body=await r.text();if(!body.trimStart().startsWith('{'))throw new Error('non-JSON');
        const parsed=JSON.parse(body);if(!Array.isArray(parsed.items))throw new Error('no items');
        const file=resolve(dir,`1000-${offset}.json`);const tmp=`${file}.tmp-${process.pid}`;await writeFile(tmp,body);await rename(tmp,file);ok=true;
        const pdfOnly=parsed.items.filter(it=>!it.urls?.GeoTIFF&&it.urls?.GeoPDF).length;
        done++;console.log(`offset ${offset}: ${parsed.items.length} items, ${pdfOnly} GeoPDF-only (${done}/${offsets.length})`);
