import test from "node:test";
import assert from "node:assert/strict";
import { stanfordRecord, parseEnvelope } from "../scripts/stanford-records.mjs";
import {
  openImageRights,
  locRecord,
  leventhalRecord,
  usgsRecord,
  catalogueResponse,
} from "../src/worker/catalogue.js";

// Representative institutional schema fixtures, not imported collection records.
const metadata = () => ({
  id: "stanford-ab123cd4567",
  dct_title_s: "An undated map",
  dct_accessRights_s: "Public",
  gbl_resourceClass_sm: ["Maps"],
  dct_rights_sm: ["This work is in the public domain."],
  dct_license_sm: ["https://creativecommons.org/publicdomain/mark/1.0/"],
  dct_references_s: JSON.stringify({
    "http://schema.org/url": "https://purl.stanford.edu/ab123cd4567",
  }),
});
test("rights-cleared scans survive missing dates, thumbnails, extents and alignment", () => {
  const record = stanfordRecord(metadata(), "fixture.json");
  assert.ok(record);
  for (const field of ["yearStart", "yearEnd", "thumbnail", "extent", "geo"])
    assert.equal(record[field], null);
  assert.equal(record.georeference, undefined);
  assert.match(record.metadataSource, /blob\/[a-f0-9]{40}\/fixture.json$/);
});
test("public access never substitutes for reusable image rights", () => {
  for (const patch of [
    { dct_license_sm: [] },
    { dct_rights_sm: [] },
    { dct_accessRights_s: "Restricted" },
    { dct_license_sm: ["https://creativecommons.org/licenses/by-nc/4.0/"] },
    { dct_rights_sm: ["All rights reserved."] },
  ])
    assert.equal(
      stanfordRecord({ ...metadata(), ...patch }, "fixture.json"),
      null,
    );
  assert.equal(openImageRights("No known restrictions"), null);
  assert.equal(
    openImageRights("Publicly accessible. Copyright undetermined."),
    null,
  );
  assert.equal(
    openImageRights("https://creativecommons.org/licenses/by-nc/4.0/"),
    null,
  );
  assert.ok(openImageRights("This work is in the public domain."));
});
test("bounding boxes are discovery metadata, not invented raster transforms", () => {
  assert.equal(parseEnvelope("ENVELOPE(-181,10,20,0)"), null);
  const record = stanfordRecord(
    { ...metadata(), dcat_bbox: "ENVELOPE(-10,10,20,0)" },
    "fixture.json",
  );
  assert.deepEqual(record.extent, { west: -10, east: 10, north: 20, south: 0 });
  assert.equal(record.georeference, undefined);
});
test("original collection adapters require rights evidence and canonical source links", () => {
  const item = {
    id: "https://www.loc.gov/item/123/",
    title: "Map of the world",
    date: "1850",
    image_url: [],
  };
  assert.equal(locRecord(item), null);
  assert.equal(
    locRecord({
      ...item,
      rights_advisory: "This work is in the public domain.",
    }).yearStart,
    1850,
  );
  assert.equal(
    locRecord({
      ...item,
      id: "https://evil.example/item/123/",
      rights_advisory: "This work is in the public domain.",
    }),
    null,
  );
  assert.equal(
    leventhalRecord({ id: "commonwealth:abcd123", title: "Boston" }),
    null,
  );
  const boston = leventhalRecord({
    id: "commonwealth:abcd123",
    title: "Boston",
    rights_ss: ["This work is in the public domain."],
  });
  assert.equal(boston.providerId, "leventhal");
  const usgs = usgsRecord({
    sourceId: "123",
    title: "Boston, MA",
    metaUrl: "https://www.sciencebase.gov/catalog/item/123",
    boundingBox: { minX: -72, maxX: -71, minY: 42, maxY: 43 },
  });
  assert.equal(
    usgs.georeference,
    undefined,
    "a product footprint is never used as a transform",
  );
  assert.match(usgs.rights, /public domain/);
});
test("federated catalogue bounds requests and withholds unclear rights", async () => {
  const original = globalThis.fetch,
    originalCaches = globalThis.caches;
  const tasks = [];
  const seen = [];
  globalThis.caches = {
    default: { match: async () => undefined, put: async () => {} },
  };
  globalThis.fetch = async (url) => {
    seen.push(new URL(url));
    return Response.json({
      response: {
        docs: [
          {
            id: "commonwealth:abcd123",
            title: "Boston",
            rights_ss: ["This work is in the public domain."],
          },
          {
            id: "commonwealth:abcd124",
            title: "Boston",
            rights_ss: ["All rights reserved."],
          },
        ],
        numFound: 2,
      },
    });
  };
  try {
    const ctx = { waitUntil: (p) => tasks.push(p) };
    assert.equal(
      (
        await catalogueResponse(
          new Request("https://atlas.test/api/catalogue?source=evil&q=Boston"),
          ctx,
        )
      ).status,
      400,
    );
    const response = await catalogueResponse(
      new Request(
        "https://atlas.test/api/catalogue?source=leventhal&q=Boston&page=999999999",
      ),
      ctx,
    );
    const body = await response.json();
    assert.equal(body.records.length, 1);
    assert.equal(body.withheld, 1);
    assert.equal(seen[0].hostname, "collections.leventhalmap.org");
    assert.equal(seen[0].searchParams.get("per_page"), "12");
    assert.equal(body.page, 10000);
    await Promise.all(tasks);
  } finally {
    globalThis.fetch = original;
    globalThis.caches = originalCaches;
  }
});

content.thinking:
Current test asserts `openImageRights("No known restrictions") === null`. We need change that because that phrase is permissive per DC. But is bare "No known restrictions" enough? Digital Commonwealth's full rights statement is "No known copyright restrictions." plus license "No known restrictions on use." plus reuse flag. The strict approach: bare "No known restrictions" alone is ambiguous (restrictions on what? copyright? use?). We can require "no known copyright restrictions" OR ("no known restrictions on use" plus `reuse_allowed_ssi=no restrictions`). But `openImageRights` receives array; could recognize phrase "no known restrictions on use" but bare "No known restrictions" not. Keep test for bare string null; add tests for full DC bundle.

Design:
```
export function openImageRights(value) {
  const statement = text(value);
  if (!statement) return null;
  if (/non[ -]?commercial|all rights reserved|permission (?:is )?required|not in the public domain|copyright undetermined|in copyright|rights reserved|no copyright[ -]non-commercial/i.test(statement)) return null;
  if (
    /creativecommons\.org\/(?:publicdomain\/(?:mark|zero)\/1\.0|licenses\/by(?:-sa)?\/\d\.\d)/i ||
    /rightsstatements\.org\/vocab\/(?:NoC-US|PDM)\//i ||
    /\bno known copyright restrictions\b/i ||
    /\bno copyright[ -](?:united states|us)\b/i ||
    /\b(?:is|are|in the|in) (?:the )?public domain\b/i
  ) return statement;
  return null;
}
```
But DC `license_ss` "No known restrictions on use." alone is not matched; combined with `rights_ss` "No known copyright restrictions." matches. Good.
`openImageRights("No known restrictions")` stays null (test passes).
`openImageRights("No known restrictions on use.")` -> null; but if a record only has that, it won't import. Strict is fine.

Leventhal: include `rightsstatement_ss` and `reuse_allowed_ssi`. If rights_ss is "No known copyright restrictions" -> pass.
Also `rights_statement_ss` legacy retained.

LoC:
Add `locRights`:
```
export function locRights(data,d) {
  if (data.access_restricted === true || d.access_restricted === true) return null;
  const advisories = text([data.rights_advisory,d.rights_advisory]);
  const statement = text([data.rights,d.rights,advisories]);
  if (!statement) return null;
  if (/in copyright|all rights reserved|permission (?:is )?required|not in the public domain|non[ -]?commercial|restricted/i.test(advisories)) return null;
  if (/free to use and reuse/i.test(statement) && !/rights advisory statement is present/i?) ...
```
Careful: statement includes "unless a Rights Advisory statement is present that indicates otherwise"; if no advisory, fine. Pattern `/free to use and reuse/i` is affirmative. But if `rights` also contains "Copyright and other Restrictions" it's a link title, not a restriction. Do not reject "restricted" generic in statement.
Also `access_restricted` could be string "false"? Boolean false normally. Treat truthy except false/"false".
```
const restricted = data.access_restricted === true || d.access_restricted === true || text(...) === 'true';
```
If item has `rights_advisory` and it says "In Copyright", reject. If it says "No known copyright restrictions", pass.
Then openImageRights fallback for explicit PD/CC.
`recordUrl`: use `d.itemUrl ?? data.itemUrl ?? d.url ?? data.url ?? d.id`; normalize http->https for approved host:
```
function httpsUpgrade(value, hosts) { const u=https(value,hosts); if(u)return u; const s=String(value); if(s.startsWith('http://')) return https('https://'+s.slice(7),hosts); return null; }
```
`id` extraction regex expects `/item/([^/]+)/`. itemUrl works.
`thumbnail`: prefer IIIF derivative:
```
const images=(data.image_url??d.image_url??[]).filter(v=>https(v,...));
const image = images.find(v=>/\/image-services\/iiif\//.test(v)) ?? images.find(v=>/\/full\//.test(v)) ?? images[0] ?? null;
```
`image_url` entries may include `#h=..&w=..` fragments; `https()` allows fragments (it doesn't reject hash). Browser image URL with fragment still works. Fine.
`manifest`: `iiif_presentation_manifest` absent; fallback to `https://www.loc.gov/item/${id}/manifest.json` (known 403). Keep.
`creators`: `d.contributor` may be array of strings/objects; text handles arrays. Add `d.creator`.
`subjectPlace`: text location array.

Live LoC search: `documents` from `data.results`; first result `id: http://lccn.loc.gov/2006577703`, `url: //lccn.loc.gov/2006577703`; code's item URL check `https(document.id ?? document.url, ["www.loc.gov"])` returns null (host lccn.loc.gov, protocol http/relative), so it won't fetch item. That's okay for odd LCCN record (no image). For normal `https://www.loc.gov/item/...`, it fetches. Search results are filtered? The `/maps/` collection may include non-map formats; could restrict to `original_format` maps? Not necessary; rights gate and item records identify maps. But title "Civil War maps" first result is a collection-level record from lccn; skip.
Also throttle item fetches: chunks of 3 sequential; 12 items -> 4 batches, each 3 parallel. Good.

Test live search endpoint with local Worker later.

Let's patch.

