cd /home/runner/work/maps-n-stuff/maps-n-stuff && python3 - <<'PY'
from pathlib import Path
p=Path('scripts/erara-depth.mjs');s=p.read_text()
s=s.replace("import { openImageRights } from '../src/worker/catalogue.js';\n","")
s=s.replace("""/** The image-rights gate. Only an explicit PDM/CC0/PD statement passes. */
export function eligibleRights(rights) {
  const value = String(rights ?? '').trim();
  if (!value) return false;
  if (/^PDM\\s*1\\.0$/i.test(value)) return true;
  return Boolean(openImageRights(value));
}""","""/** The image-rights gate. Only an explicit PDM/CC0/public-domain statement passes. */
export function eligibleRights(rights) {
  const value = String(rights ?? '').trim();
  if (!value) return false;
  if (/^PDM\\s*1\\.0$/i.test(value)) return true;
  if (/creativecommons\\.org\\/publicdomain\\/(?:mark|zero)\\/1\\.0/i.test(value)) return true;
  // e-rara states the licence per item; a generic "no known restrictions"
  // record is not the explicit PDM/CC0 grant this gate requires.
  return /\\b(?:is|are|in the|in) (?:the )?public domain\\b/i.test(value);
}""")
p.write_text(s)
PY
node --test tests/erara-depth.test.mjs 2>&1 | tail -10

